'use strict';
const $=s=>document.querySelector(s), app=$('#app'), KEY='word-garden-v1';
const fresh=()=>({stars:[],records:[],selected:FAMILIES.map(f=>f.id),special:false,rate:.85,voice:''});
let state=fresh(), storageOK=true;
try {const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&Array.isArray(s.stars)&&Array.isArray(s.records))state={...state,...s};}catch(e){storageOK=false;}
state.stars=state.stars.filter(id=>WORDS.some(w=>w.id===id));state.selected=state.selected.filter(id=>FAMILIES.some(f=>f.id===id));
let tab='home', mode='review', session=null, voices=[], month=new Date(), toastTimer;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;toast('瀏覽器暫時無法儲存，請匯出日記備份。');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function dateKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function pool(){return WORDS.filter(w=>state.selected.includes(w.family)&&(state.special||!w.special));}
function stars(){return WORDS.filter(w=>state.stars.includes(w.id));}
function updateCount(){$('#star-count').textContent=state.stars.length;}
function toggleStar(id){const on=state.stars.includes(id);state.stars=on?state.stars.filter(x=>x!==id):[...state.stars,id];save();updateCount();return !on;}
function markStar(id){if(!state.stars.includes(id)){state.stars.push(id);save();updateCount();}}
function englishVoices(){if(!('speechSynthesis' in window))return;voices=speechSynthesis.getVoices().filter(v=>/^en[-_]/i.test(v.lang)||v.lang==='en');const select=$('#voice');select.innerHTML='<option value="">自動選擇英文聲音</option>';voices.forEach(v=>{const o=document.createElement('option');o.value=v.voiceURI;o.textContent=`${v.name} (${v.lang})`;select.append(o);});select.value=state.voice;$('#voice-status').textContent=voices.length?'已找到英文語音，可以開始試聽。':'目前未列出英文語音，可先試聽或安裝裝置英文語音。';}
function speak(word,slow=false){if(!('speechSynthesis' in window)){toast('這個瀏覽器沒有語音功能，請使用支援語音的 Chrome、Edge 或 Safari。');return;}speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(word==='pam'?'Pam':word);utter.lang='en-US';utter.voice=voices.find(v=>v.voiceURI===state.voice)||voices.find(v=>v.lang==='en-US')||voices[0]||null;utter.rate=slow?.55:Number(state.rate);utter.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('聲音沒有播放成功，請檢查裝置英文語音與音量。');};speechSynthesis.speak(utter);}
function stopSpeech(){if('speechSynthesis' in window)speechSynthesis.cancel();}
function gardenArt(){return `<div class="garden" aria-hidden="true"><svg viewBox="0 0 400 230"><ellipse cx="203" cy="203" rx="156" ry="17" fill="#dce5cc"/><path d="M81 142q20-63 0-79M199 143q-2-64 8-80M314 144q-13-43-1-60" stroke="#6b9972" stroke-width="7" fill="none"/><path d="M83 114q-38-38-39-8q2 26 39 22M201 109q33-37 38-8q-3 20-36 24M312 124q-37-29-43-8q5 22 43 17" fill="#82aa78"/><g fill="#e8ae6b"><circle cx="78" cy="53" r="18"/><circle cx="59" cy="66" r="18"/><circle cx="97" cy="65" r="18"/><circle cx="69" cy="86" r="18"/><circle cx="91" cy="86" r="18"/></g><circle cx="79" cy="72" r="20" fill="#ffdf85"/><circle cx="74" cy="70" r="2" fill="#435845"/><circle cx="85" cy="70" r="2" fill="#435845"/><path d="M73 78q7 7 13 0" stroke="#435845" stroke-width="2" fill="none"/><g fill="#b7b9e1"><circle cx="208" cy="35" r="19"/><circle cx="188" cy="53" r="19"/><circle cx="228" cy="52" r="19"/><circle cx="197" cy="73" r="19"/><circle cx="221" cy="72" r="19"/></g><circle cx="208" cy="55" r="20" fill="#ffedb8"/><circle cx="201" cy="53" r="2" fill="#435845"/><circle cx="214" cy="53" r="2" fill="#435845"/><path d="M201 61q7 7 14 0" stroke="#435845" stroke-width="2" fill="none"/><g fill="#dd987e"><circle cx="314" cy="67" r="16"/><circle cx="295" cy="79" r="16"/><circle cx="331" cy="81" r="16"/><circle cx="304" cy="99" r="16"/><circle cx="324" cy="100" r="16"/></g><circle cx="314" cy="86" r="18" fill="#ffdf85"/><circle cx="309" cy="84" r="2" fill="#435845"/><circle cx="320" cy="84" r="2" fill="#435845"/><path d="M308 92q7 6 13 0" stroke="#435845" stroke-width="2" fill="none"/><path d="M42 142h81l-10 58H54Z" fill="#dba17d"/><path d="M164 142h85l-11 61h-64Z" fill="#6b917b"/><path d="M278 145h78l-9 52h-59Z" fill="#dfbd6f"/><g fill="#fff5df" font-family="Nunito,sans-serif" font-size="30" font-weight="900" text-anchor="middle"><text x="83" y="182">a</text><text x="207" y="183">e</text><text x="317" y="181">i</text></g><path d="M350 31l4 9 10 1-8 7 3 10-9-5-8 5 1-10-7-7 10-1Z" fill="#d9bc61"/><path d="M145 39l3 7 8 1-6 6 1 8-6-4-7 4 2-8-6-6 8-1Z" fill="#e2cfa2"/></svg></div>`;}
function render(){updateCount();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(session){renderSession();return;}if(tab==='home')renderHome();else if(tab==='stars')renderStars();else renderHistory();}
function renderHome(){const dates=new Set(state.records.map(r=>r.date)),today=state.records.filter(r=>r.date===dateKey()).reduce((a,r)=>a+r.completed,0);app.innerHTML=`<section class="hero"><div class="hero-copy"><span class="pill">🌼 每天一點點，英文長大一點點</span><h1>嗨，小小園丁！<br>今天一起種下新單字。</h1><p>聽一聽、讀一讀，讓每個單字<br>在你的小花園裡慢慢開花。</p></div>${gardenArt()}</section><div class="stats"><div class="stat"><span class="stat-icon">🌱</span><div><strong>${dates.size}</strong> 天<small>累積練習日</small></div></div><div class="stat"><span class="stat-icon">☀️</span><div><strong>${today}</strong> 個<small>今天練習的單字</small></div></div><div class="stat"><span class="stat-icon">⭐</span><div><strong>${state.stars.length}</strong> 個<small>等待複習的小星星</small></div></div></div><div class="layout"><section class="scope"><div class="section-head"><div><h2>選一塊地，開始冒險</h2><p class="muted">勾選想練習的字族，可以一次選好幾個。</p></div><div><button class="text-button" id="all">全部選取</button><button class="text-button" id="none">清除</button></div></div><div class="groups">${['a','e','i','o','u'].map(v=>`<button data-group="${v}">${v} 小花圃</button>`).join('')}</div><div class="family-grid">${FAMILIES.map(f=>`<label class="family"><input type="checkbox" value="${f.id}" ${state.selected.includes(f.id)?'checked':''}><small>第 ${f.page} 頁</small><strong>-${f.id}</strong><span class="example">${f.words[0]}</span></label>`).join('')}</div><div class="scope-foot"><span id="pool-count"></span><label><input type="checkbox" id="special" ${state.special?'checked':''}> 加入教材特殊項目</label></div><p class="muted" style="font-size:10px">特殊項目 pam、ren、lunch 預設略過；lunch 保留在原教材第 17 頁。-${'it'} / -ut 也包含 mitt / putt。</p></section><aside class="side"><section class="mission"><span class="tag">TODAY’S LITTLE ADVENTURE</span><h2 style="margin-top:8px">今天想怎麼玩？</h2><div class="mode-picker"><button data-mode="review" class="${mode==='review'?'active':''}">📖 複習</button><button data-mode="quiz" class="${mode==='quiz'?'active':''}">🎯 測驗</button></div><p id="mode-note" class="muted"></p><label>這次練習幾個單字？<select id="limit"><option value="10">10 個 · 小小冒險</option><option value="20">20 個 · 大步前進</option><option value="0">選取範圍全部</option></select></label><button id="start" class="primary wide">出發吧！ →</button><p class="muted" style="font-size:10px;margin-top:13px">🔊 點按喇叭即可聽英文發音</p></section><section class="pocket-card"><h3>⭐ 星星口袋</h3><p>不熟悉的字先收起來，<br>下次一起把它學會。</p><button id="quick">快速複習 ${state.stars.length} 個星星 →</button></section><div class="tip"><span>💡</span><span>大聲跟著讀，再按「我練習好了」。每天五分鐘，也是一朵小進步。</span></div></aside></div><p class="footer-note">依 20 頁拼讀教材整理 · 紀錄儲存在這個瀏覽器${storageOK?'':' · 目前儲存不可用，請匯出備份'}</p>`;
$('#all').onclick=()=>{state.selected=FAMILIES.map(f=>f.id);save();render();};$('#none').onclick=()=>{state.selected=[];save();render();};document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{const ids=FAMILIES.filter(f=>f.vowel===b.dataset.group).map(f=>f.id),all=ids.every(id=>state.selected.includes(id));state.selected=all?state.selected.filter(id=>!ids.includes(id)):[...new Set([...state.selected,...ids])];save();render();});document.querySelectorAll('.family input').forEach(i=>i.onchange=()=>{state.selected=i.checked?[...state.selected,i.value]:state.selected.filter(v=>v!==i.value);save();scopeCount();});$('#special').onchange=e=>{state.special=e.target.checked;save();scopeCount();};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));modeNote();});$('#start').onclick=()=>start(pool(),mode,Number($('#limit').value));$('#quick').onclick=()=>start(stars(),'review',0,true);scopeCount();modeNote();}
function scopeCount(){const n=pool().length;$('#pool-count').textContent=`已選 ${state.selected.length} 個字族 · ${n} 個單字`;$('#start').disabled=!n;}
function modeNote(){$('#mode-note').textContent=mode==='review'?'看單字、聽發音，再跟著大聲讀。':'聽英文發音，選出正確單字。答錯會放進星星口袋。';}
function start(items,type,limit,quick=false){if(!items.length){toast(quick?'先把不熟悉的單字加上星星吧！':'先勾選一個字族吧！');return;}if(type==='quiz'&&new Set(items.map(w=>w.word.toLowerCase())).size<2){toast('測驗需要至少兩個不同單字，先用複習模式練習吧！');return;}session={items:shuffle(items).slice(0,limit||items.length),source:items,type,index:0,correct:0,completed:0,wrong:[],answered:false,quick,started:Date.now(),recordId:null,done:false};render();if(type==='quiz')speak(session.items[0].word);}
function current(){return session.items[session.index];}
function recordProgress(){const s=session;if(!s.completed)return;const record={id:s.recordId||`${Date.now()}-${Math.random().toString(36).slice(2,6)}`,date:dateKey(),type:s.type,quick:s.quick,completed:s.completed,total:s.items.length,correct:s.correct,finished:s.done,families:[...new Set(s.items.map(w=>w.family))],wrong:[...s.wrong]};if(!s.recordId){s.recordId=record.id;state.records.push(record);}else{const i=state.records.findIndex(r=>r.id===s.recordId);if(i>=0)state.records[i]=record;}save();}
function renderSession(){const s=session;if(s.done){renderResult();return;}const w=current();app.innerHTML=`<div class="session-head"><button id="exit">← 回到花園</button><h2>${s.quick?'⭐ 星星複習':s.type==='review'?'📖 跟讀小冒險':'🎯 聽音選字挑戰'}</h2><span class="badge">${s.index+1} / ${s.items.length}</span></div><div class="progress"><div style="width:${s.completed/s.items.length*100}%"></div></div><section class="play-card"><span class="eyebrow">${s.type==='review'?`第 ${w.page} 頁 · ${w.word==='lunch'?'教材特殊項目':`-${w.family} 字族`}`:'LISTEN & FIND · 聽聽是哪個字'}</span>${s.type==='review'?`<div class="big-emoji" aria-hidden="true">🌼</div><div class="word">${highlight(w)}</div><p class="muted">先聽一遍，再自己大聲讀一遍。</p>`:`<div class="big-emoji" aria-hidden="true">🎧</div><h2>小耳朵準備好了嗎？</h2><p class="muted">按喇叭聽英文，再選出你聽到的字。</p>`}<div class="audio-actions"><button id="listen">🔊 ${s.type==='review'?'聽發音':'再聽一次'}</button><button id="slow">🐢 慢慢聽</button></div>${s.type==='quiz'?'<div class="choices" id="choices"></div><div id="feedback" class="feedback" role="status" aria-live="polite"></div>':''}<div class="practice-actions"><button id="star" class="star-button ${state.stars.includes(w.id)?'selected':''}">${state.stars.includes(w.id)?'★ 已放進星星口袋':'☆ 這個字我還不熟'}</button><button id="next" class="primary" ${s.type==='quiz'&&!s.answered?'disabled':''}>${s.type==='review'?'我練習好了 →':'下一題 →'}</button></div>${w.special&&s.type==='review'?'<p class="muted">這是原教材保留的特殊項目，適合和大人一起確認讀音。</p>':''}<p class="keyboard-tip">空白鍵：聽發音 · ${s.type==='review'?'→：下一個':'1–4：選答案'} · S：收藏星星</p></section>`;
$('#exit').onclick=()=>{stopSpeech();recordProgress();session=null;render();};$('#listen').onclick=()=>speak(w.word);$('#slow').onclick=()=>speak(w.word,true);$('#star').onclick=()=>{toggleStar(w.id);const b=$('#star');b.classList.toggle('selected',state.stars.includes(w.id));b.textContent=state.stars.includes(w.id)?'★ 已放進星星口袋':'☆ 這個字我還不熟';};$('#next').onclick=next;
if(s.type==='quiz'){if(!s.options){const others=shuffle(s.source.filter(x=>x.word.toLowerCase()!==w.word.toLowerCase()));const unique=[];const seen=new Set([w.word.toLowerCase()]);for(const x of others){if(!seen.has(x.word.toLowerCase())){seen.add(x.word.toLowerCase());unique.push(x);}if(unique.length===3)break;}s.options=shuffle([w,...unique]);}s.options.forEach((x,i)=>{const b=document.createElement('button');b.textContent=x.word;b.dataset.id=x.id;b.onclick=()=>answer(x.id);$('#choices').append(b);});}}
function highlight(w){if(!w.word.toLowerCase().endsWith(w.family))return w.word;const cut=w.word.length-w.family.length;return `${w.word.slice(0,cut)}<em>${w.word.slice(cut)}</em>`;}
function answer(id){const s=session;if(!s||s.answered||s.type!=='quiz')return;s.answered=true;const w=current(),ok=id===w.id;s.completed++;if(ok)s.correct++;else{s.wrong.push(w.id);markStar(w.id);}document.querySelectorAll('.choices button').forEach(b=>{b.disabled=true;if(b.dataset.id===w.id)b.classList.add('correct');else if(b.dataset.id===id)b.classList.add('wrong');});$('#feedback').textContent=ok?'🌟 答對了！你的單字又開花了。':`🌱 沒關係，答案是 ${w.word}，已加入星星口袋。`;$('#next').disabled=false;recordProgress();}
function next(){const s=session;if(!s||s.done||(s.type==='quiz'&&!s.answered))return;stopSpeech();if(s.type==='review')s.completed++;if(s.index===s.items.length-1){s.done=true;recordProgress();render();return;}recordProgress();s.index++;s.answered=false;s.options=null;render();}
function renderResult(){const s=session;app.innerHTML=`<section class="play-card"><div class="big-emoji celebrate">🌻</div><span class="eyebrow">A LITTLE GROWTH EVERY DAY</span><h1>今天的小花開了！</h1><p>${s.type==='review'?'你完成了一次很棒的跟讀練習。':'每一次嘗試，都讓你更熟悉英文。'}</p><div class="result-number">${s.type==='quiz'?s.correct:s.completed}<span style="font-size:25px;color:var(--muted)"> / ${s.items.length}</span></div><p class="muted">${s.type==='quiz'?'答對的單字':'練習完成的單字'}</p><div class="result-summary">📅 ${dateKey()} · 已${storageOK?'記在你的成長日記':'完成，紀錄暫時無法儲存'}${s.wrong.length?`<br>⭐ ${s.wrong.length} 個待複習單字已加入星星口袋`:''}</div><div class="practice-actions">${s.wrong.length?'<button id="retry" class="star-button">⭐ 複習這次答錯的字</button>':''}<button id="back" class="primary">回到花園 →</button></div></section>`;$('#back').onclick=()=>{session=null;tab='home';render();};if($('#retry'))$('#retry').onclick=()=>start(WORDS.filter(w=>s.wrong.includes(w.id)),'review',0,true);}
function renderStars(){const list=stars();app.innerHTML=`<div class="section-head"><div><span class="eyebrow">MY LITTLE STAR POCKET</span><h1>星星口袋</h1><p class="muted">不熟悉的字，陪它多練習幾次。學會後就可以摘下星星。</p></div><div><button id="star-review" class="primary">📖 全部快速複習</button> <button id="star-quiz">🎯 星星測驗</button></div></div>${list.length?`<div class="word-list">${list.map(w=>`<article class="word-tile"><span class="muted">第 ${w.page} 頁 · -${w.family}</span><div><strong>${w.word}</strong></div><div class="actions"><button data-speak="${w.id}" aria-label="朗讀 ${w.word}">🔊 聽一聽</button><button data-remove="${w.id}" aria-label="將 ${w.word} 移出星星口袋">✓ 學會了</button></div></article>`).join('')}</div>`:'<section class="empty"><div class="big-emoji">⭐</div><h2>你的星星口袋還是空的</h2><p class="muted">練習時按「這個字我還不熟」，就會出現在這裡。</p><button class="primary" id="empty-home">開始種單字 →</button></section>'}`;$('#star-review').onclick=()=>start(list,'review',0,true);$('#star-quiz').onclick=()=>start(list,'quiz',0,true);document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(WORDS.find(w=>w.id===b.dataset.speak).word));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{toggleStar(b.dataset.remove);renderStars();toast('學會一個字！你的花園又長大了。');});if($('#empty-home'))$('#empty-home').onclick=()=>{tab='home';render();};}
function renderHistory(){const y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1).getDay(),last=new Date(y,m+1,0).getDate(),dates=new Set(state.records.map(r=>r.date));let cells=Array(first).fill('<div></div>').join('');for(let d=1;d<=last;d++){const key=dateKey(new Date(y,m,d)),done=dates.has(key);cells+=`<div class="day ${done?'done':''} ${key===dateKey()?'today':''}" title="${key}${done?' 已練習':''}">${d}${done?'<br>🌱':''}</div>`;}app.innerHTML=`<div class="section-head"><div><span class="eyebrow">MY GROWING JOURNAL</span><h1>成長日記</h1><p class="muted">每個有練習的日子，都是一顆發芽的小種子。</p></div><button id="export">↓ 匯出日記備份</button></div><div class="history-grid"><section class="scope"><div class="calendar-head"><button id="prev-month" aria-label="上一個月">←</button><h2>${y} 年 ${m+1} 月</h2><button id="next-month" aria-label="下一個月">→</button></div><div class="calendar">${'日一二三四五六'.split('').map(d=>`<div class="muted" style="text-align:center">${d}</div>`).join('')}${cells}</div><p class="muted">🌱 有完成單字的日子 · 外框表示今天</p></section><section class="scope"><h2>我的冒險紀錄</h2>${state.records.length?[...state.records].reverse().slice(0,30).map(r=>`<div class="record"><div><p><strong>${r.date}</strong> · ${r.quick?'星星':''}${r.type==='quiz'?'測驗':'複習'}</p><span class="muted">${r.completed} / ${r.total} 個${r.finished?' · 已完成':' · 練習中途離開'}</span></div><span class="badge">${r.type==='quiz'?`答對 ${r.correct} 個`:'📖 跟讀'}</span></div>`).join(''):'<p class="muted">完成第一個單字後，這裡就會有你的紀錄。</p>'}<p class="muted" style="font-size:11px">顯示最近 30 次紀錄。日記備份包含全部紀錄。</p></section></div><p class="footer-note">紀錄只保存在這個瀏覽器，清除網站資料會移除紀錄。不同裝置各自記錄。</p>`;$('#prev-month').onclick=()=>{month=new Date(y,m-1,1);renderHistory();};$('#next-month').onclick=()=>{month=new Date(y,m+1,1);renderHistory();};$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`word-garden-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);};}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(session)recordProgress();session=null;stopSpeech();tab=b.dataset.tab;render();});$('.brand').onclick=e=>{e.preventDefault();if(session)recordProgress();session=null;stopSpeech();tab='home';render();};$('#settings-button').onclick=()=>{englishVoices();$('#speed').value=String(state.rate);$('#settings').showModal();};$('#voice').onchange=e=>{state.voice=e.target.value;save();};$('#speed').onchange=e=>{state.rate=Number(e.target.value);save();};$('#test-voice').onclick=()=>speak('hello');if('speechSynthesis' in window){speechSynthesis.addEventListener('voiceschanged',englishVoices);englishVoices();}
document.addEventListener('keydown',e=>{if(!session||session.done||$('#settings').open||['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();speak(current().word);}else if(e.key==='ArrowRight')next();else if(e.key.toLowerCase()==='s')$('#star')?.click();else if(session.type==='quiz'&&/^[1-4]$/.test(e.key)){const b=document.querySelectorAll('.choices button')[Number(e.key)-1];b?.click();}});
window.addEventListener('pagehide',()=>{if(session)recordProgress();});render();
